public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) return 0;
    int rows = grid.length;
    int cols = grid[0].length;
    if (cols == 0) return 0;

    boolean[][] visited = new boolean[rows][cols];
    int deposits = 0;

    int[] dRow = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dCol = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int r = 0; r < rows; r++) {
        // Handle possibly jagged rows
        if (grid[r] == null) continue;
        for (int c = 0; c < grid[r].length; c++) {
            if (grid[r][c] != '@' || visited[r][c]) continue;
            deposits++;
            // DFS to mark all connected '@' cells
            java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();
            stack.push(new int[]{r, c});
            visited[r][c] = true;

            while (!stack.isEmpty()) {
                int[] pos = stack.pop();
                int cr = pos[0], cc = pos[1];
                for (int d = 0; d < 8; d++) {
                    int nr = cr + dRow[d];
                    int nc = cc + dCol[d];
                    if (nr < 0 || nr >= rows) continue;
                    if (grid[nr] == null) continue;
                    if (nc < 0 || nc >= grid[nr].length) continue;
                    if (!visited[nr][nc] && grid[nr][nc] == '@') {
                        visited[nr][nc] = true;
                        stack.push(new int[]{nr, nc});
                    }
                }
            }
        }
    }
    return deposits;
}

public static int countPrefixWords(List<String> wordList, String prefix) {
    if (wordList == null || prefix == null) {
        return 0;
    }
    int count = 0;
