public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) return false;
    if (k == 0) return false;
    k = Math.abs(k);
    int[] freq = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k;
        freq[rem]++;
    }
    // Remainder 0 must appear an even number of times
    if (freq[0] % 2 != 0) return false;
    // If k is even, remainder k/2 also has to appear an even number of times
    if (k % 2 == 0 && freq[k / 2] % 2 != 0) return false;
    // For all other remainders, freq[r] must equal freq[k-r]
    for (int r = 1; r < k; r++) {
        if (r == k - r) continue; // already handled when k even
        if (freq[r] != freq[k - r]) return false;
    }
    return true;
}

