public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    int[] freq = new int[256];
    for (char c : s.toCharArray()) {
        freq[c]++;
    }
    int remaining = s.length();
    StringBuilder result = new StringBuilder(s.length());
    while (remaining > 0) {
        // Increasing phase
        int prev = -1;
        for (int i = 0; i < 256 && remaining > 0; i++) {
            if (freq[i] > 0) {
                if (prev == -1) {
                    result.append((char) i);
                    freq[i]--;
                    remaining--;
                    prev = i;
                } else if (i > prev) {
                    result.append((char) i);
                    freq[i]--;
                    remaining--;
                    prev = i;
                }
            }
        }
        // Decreasing phase
        prev = -1;
        for (int i = 255; i >= 0 && remaining > 0; i--) {
            if (freq[i] > 0) {
                if (prev == -1) {
                    result.append((char) i);
                    freq[i]--;
                    remaining--;
                    prev = i;
                } else if (i < prev) {
                    result.append((char) i);
                    freq[i]--;
                    remaining--;
                    prev = i;
                }
            }
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) return false;
    int n = nums.length;
    long totalSum = 0;
    for (int v : nums) totalSum += v;
    // dp[k] will hold all possible sums for subsets of size k
    @SuppressWarnings("unchecked")
    HashSet<Integer>[] dp = new HashSet[n + 1];
    for (int i = 0; i <= n; i++) dp[i] = new HashSet<>();
    dp[0].add(0);
    int maxK = 0;
    for (int num : nums) {
        // iterate sizes in reverse to avoid overwriting current iteration
        for (int k = maxK; k >= 0; k--) {
            HashSet<Integer> current = dp[k];
            if (current.isEmpty()) continue;
            HashSet<Integer> targetSet = dp[k + 1];
            for (int sum : current) {
                long newSum = (long) sum + num;
                if (newSum <= Integer.MAX_VALUE && newSum >= Integer.MIN_VALUE) {
                    targetSet.add((int) newSum);
                }
            }
        }
        maxK++;
        // Optional early exit: if we can achieve target with size k already
    }
    // Check for any k where target sum is reachable
    for (int k = 1; k <= n / 2; k++) {
        if (totalSum * k % n != 0) continue;
        int target = (int) (totalSum * k / n);
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Input cost array cannot be null");
    }
    int n = cost.length;
    switch (n) {
        case 0:
            return 0;
        case 1:
            // If there's only one step, we can start on a higher step and pay nothing
            return 0;
        default:
            // We only need to keep track of the last two computed values
            int twoBack = cost[0];
            int oneBack = cost[1];
            int current = 0;
            for (int i = 2; i < n; i++) {
                current = Math.min(twoBack, oneBack) + cost[i];
                twoBack = oneBack;
                oneBack = current;
            }
            return Math.min(twoBack, oneBack);
    }
}

public int uniqueMorseRepresentations(String[] words) {
    if (words == null || words.length == 0) {
        return 0;
    }
    final String[] morse = {".-","-...","-.-.","-..",".","..-.","--.",
                            "....","..",".---","-.-",".-..","--","-.",
                            "---",".--.","--.-",".-.","...","-","..-",
                            "...-",".--","-..-","-.--","--.."};
    java.util.Set<String> unique = new java.util.HashSet<>();
    for (String word : words) {
        if (word == null) {
            continue;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < word.length(); i++) {
            char c = word.charAt(i);
            int idx;
            if (c >= 'a' && c <= 'z') {
                idx = c - 'a';
            } else if (c >= 'A' && c <= 'Z') {
                idx = c - 'A';
            } else {
                continue; // skip non‑alphabetic characters
            }
            sb.append(morse[idx]);
        }
        unique.add(sb.toString());
    }
    return unique.size();
}

