public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int balance = 0;      // number of unmatched '('
    int missingLeft = 0;  // number of '(' needed before a ')'
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance > 0) {
                balance--; // match with an unmatched '('
            } else {
                missingLeft++; // need an extra '(' before this ')'
            }
        } else {
            // invalid character, skip or treat as error
            // here we simply ignore it
        }
    }
    return missingLeft + balance; // remaining '(' need ')' to close
}

