public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty");
    }

    int maxEnd = nums[0];
    int maxGlobal = nums[0];
    int minEnd = nums[0];
    int minGlobal = nums[0];

    for (int i = 1; i < nums.length; i++) {
        int val = nums[i];

        // Update maximum subarray ending at current position
        maxEnd = Math.max(val, maxEnd + val);
        maxGlobal = Math.max(maxGlobal, maxEnd);

        // Update minimum subarray ending at current position
        minEnd = Math.min(val, minEnd + val);
        minGlobal = Math.min(minGlobal, minEnd);
    }

    // The maximum absolute sum is the larger of maximum sum or absolute value of minimum sum
    return Math.max(maxGlobal, -minGlobal);
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("k must be a positive integer");
    }
    // Fibonacci numbers list (using int array to avoid imports)
    int[] fib = new int[45]; // there are at most 44 Fibonacci numbers <= Integer.MAX_VALUE
    int size = 0;
    fib[size++] = 1;
    fib[size++] = 2;
    while (true) {
        long next = (long) fib[size - 1] + fib[size - 2];
        if (next > k) {
            break;
        }
        fib[size++] = (int) next;
    }

    int count = 0;
    int remaining = k;
    for (int i = size - 1; i >= 0 && remaining > 0; i--) {
        if (fib[i] <= remaining) {
            remaining -= fib[i];
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    int limit = (int) Math.sqrt(n);
    int[] small = new int[limit + 1];
    int[] large = new int[limit + 1];
    int smallCount = 0;
    int largeCount = 0;
    for (int i = 1; i <= limit; i++) {
        if (n % i == 0) {
            small[smallCount++] = i;
            int other = n / i;
            if (other != i) {
                large[largeCount++] = other;
            }
        }
    }
    // Reverse the large array to ascending order
    for (int i = 0; i < largeCount / 2; i++) {
        int temp = large[i];
        large[i] = large[largeCount - 1 - i];
        large[largeCount - 1 - i] = temp;
    }
    int total = smallCount + largeCount;
    if (k > total) {
        return -1;
    }
    if (k <= smallCount) {
        return small[k - 1];
    } else {
        int idx = k - smallCount - 1;
        return large[idx];
    }
}

public String makeGood(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char current = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char top = stack.charAt(len - 1);
            // If top and current are the same letter in opposite cases, remove top and skip adding current
            if (Math.abs(current - top) == 32) {
                stack.deleteCharAt(len - 1);
                continue;
            }
        }
        stack.append(current);
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int[] max = {0};
    java.util.HashSet<String> used = new java.util.HashSet<>();
    dfs(s, 0, used, max);
