}

private void dfs(String s, int index, java.util.HashSet<String> used, int[] max) {
    if (index == s.length()) {
        if (used.size() > max[0]) {
            max[0] = used.size();
        }
        return;
    }
    for (int end = index + 1; end <= s.length(); end++) {
        String sub = s.substring(index, end);
        if (!used.contains(sub)) {
            used.add(sub);
            dfs(s, end, used, max);
            used.remove(sub);
        }
    }
}

public int minOperations(String[] logs) {
