        } else if ("./".equals(log)) {
            // stay in the current directory
        } else if (log.endsWith("/")) {
            depth++;
        } // other strings are ignored
    }
    return depth;
}

public String getSmallestString(int n, int k) {
    if (n <= 0) {
        return "";
    }
    if (k < n || k > 26L * n) {
        // Impossible to construct a string with given constraints.
        return "";
    }
    char[] result = new char[n];
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    int remaining = k - n; // amount of value to distribute beyond the 'a's
    int index = n - 1;
    while (remaining > 0 && index >= 0) {
        int add = Math.min(25, remaining); // max we can add to a single character
        result[index] = (char) ('a' + add);
        remaining -= add;
        index--;
    }
    return new String(result);
}

public static double calculateProbability(int n) {
    // Handle invalid input: if n is less than or equal to 0, probability is undefined.
    // For our purposes, we return 0.0 for non-positive n.
    if (n <= 0) {
        return 0.0;
    }
    // For a single passenger, the last passenger sits in their own seat with certainty.
    if (n == 1) {
        return 1.0;
    }
    // For two or more passengers, the probability is exactly 1/2.
    return 0.5;
}

public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array cannot be null or empty");
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int sum = 0;
        for (int num : nums) {
            sum += (num >> i) & 1;
        }
        if ((sum % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
