        if (curr == 0) { // special case: from 0 only generate 1
            long next = curr * 10 + 1;
            if (next <= high && !visited.contains(next)) {
                visited.add(next);
                queue.offer(next);
            }
            continue;
        }
        // generate next by lastDigit-1
        if (lastDigit > 0) {
            long next = curr * 10 + (lastDigit - 1);
            if (next <= high && !visited.contains(next)) {
                visited.add(next);
                queue.offer(next);
            }
        }
        // generate next by lastDigit+1
        if (lastDigit < 9) {
            long next = curr * 10 + (lastDigit + 1);
            if (next <= high && !visited.contains(next)) {
                visited.add(next);
                queue.offer(next);
            }
        }
    }

    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    while (n / factor > 0) {
        long lower = n % factor;
        long cur = (n / factor) % 10;
        long higher = n / (factor * 10);
        if (cur == 0) {
            count += higher * factor;
        } else if (cur == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
        if (factor > Integer.MAX_VALUE / 10) { // avoid overflow of factor * 10
            break;
        }
        factor *= 10;
    }
    return (int) count;
}

public static boolean isPowerOfTwo(int n) {
    if (n <= 0) {
        return false;
    }
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    if (num == 0) {
        return 0;
    }
    // Use the digital root formula: 1 + (n - 1) % 9
    return 1 + (num - 1) % 9;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    if (n == 0) {
        return 0;
    }
    // Validate matrix shape and values
    for (int i = 0; i < m; i++) {
        if (mat[i] == null || mat[i].length != n) {
            throw new IllegalArgumentException("All rows must be non‑null and of equal length");
        }
        for (int j = 0; j < n; j++) {
            if (mat[i][j] != 0 && mat[i][j] != 1) {
                throw new IllegalArgumentException("Matrix may only contain 0s and 1s");
            }
        }
    }
    int[][] horiz = new int[m][n];
    int[][] vert = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] anti = new int[m][n];
    int max = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horiz[i][j] = (j > 0 ? horiz[i][j - 1] : 0) + 1;
                vert[i][j] = (i > 0 ? vert[i - 1][j] : 0) + 1;
                diag[i][j] = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                anti[i][j] = (i > 0 && j + 1 < n ? anti[i - 1][j + 1] : 0) + 1;
                int currentMax = Math.max(Math.max(horiz[i][j], vert[i][j]),
                                           Math.max(diag[i][j], anti[i][j]));
                if (currentMax > max) {
                    max = currentMax;
                }
            } else {
                horiz[i][j] = vert[i][j] = diag[i][j] = anti[i][j] = 0;
            }
        }
    }
    return max;
}

public static String addThousandSeparator(int n) {
    // Handle zero specially to avoid unnecessary logic
    if (n == 0) {
        return "0";
    }

    // Work with absolute value to avoid negative sign during formatting
    boolean negative = n < 0;
    long absVal = Math.abs((long) n); // cast to long to handle Integer.MIN_VALUE

    String numStr = Long.toString(absVal);
    StringBuilder sb = new StringBuilder();

    int counter = 0;
    // Build result in reverse: append digits from end, inserting '.' after every three digits
    for (int i = numStr.length() - 1; i >= 0; i--) {
        sb.append(numStr.charAt(i));
        counter++;
        if (counter % 3 == 0 && i != 0) {
            sb.append('.');
        }
    }

    // Add negative sign if needed
    if (negative) {
        sb.append('-');
    }

    // Reverse to obtain the correct order
    return sb.reverse().toString();
}

public static int squarePermutations(int[] A) {
    if (A == null) {
        throw new IllegalArgumentException("Input array must not be null.");
    }
    int n = A.length;
    if (n == 0) {
        // Empty array has one permutation: the empty array itself.
        return 1;
    }
    // Sort array to enable skipping duplicates during backtracking.
    int[] sorted = A.clone();
    java.util.Arrays.sort(sorted);
    boolean[] visited = new boolean[n];
    int[] current = new int[n];
    int[] count = new int[1];
    java.util.HashSet<Integer> perfectSquares = new java.util.HashSet<>();
    // Precompute perfect squares up to maximum possible sum (2 * maxValue)
    int maxVal = 0;
    for (int v : sorted) {
        if (v > maxVal) maxVal = v;
    }
    int maxSum = maxVal * 2;
    for (int i = 0; i * i <= maxSum; i++) {
        perfectSquares.add(i * i);
    }
    backtrack(0, sorted, visited, current, count, perfectSquares);
    return count[0];
}

private static void backtrack(int depth, int[] sorted, boolean[] visited, int[] current,
                              int[] count, java.util.Set<Integer> perfectSquares) {
    int n = sorted.length;
    if (depth == n) {
        count[0]++;
        return;
    }
    for (int i = 0; i < n; i++) {
        if (visited[i]) continue;
        // Skip duplicates: if the same number as previous and previous not used in this level
        if (i > 0 && sorted[i] == sorted[i - 1] && !visited[i - 1]) {
            continue;
        }
        if (depth > 0) {
            int sum = current[depth - 1] + sorted[i];
            if (!perfectSquares.contains(sum)) {
                continue;
            }
        }
        visited[i] = true;
        current[depth] = sorted[i];
        backtrack(depth + 1, sorted, visited, current, count, perfectSquares);
        visited[i] = false;
    }
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    long maxArea = 0;
    java.util.ArrayDeque<Integer> stack = new java.util.ArrayDeque<>();
    int n = heights.length;
    for (int i = 0; i <= n; i++) {
        int current = (i == n) ? 0 : heights[i];
        while (!stack.isEmpty() && current < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    return (int) maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    // Verify that all rows have the same length to avoid IndexOutOfBounds
    for (int i = 1; i < m; i++) {
        if (mat[i] == null || mat[i].length != n) {
            throw new IllegalArgumentException("All rows must be non-null and have the same length.");
        }
    }
    int total = m * n;
    int[] result = new int[total];
    int idx = 0;
    for (int d = 0; d <= m + n - 2; d++) {
        int start = Math.max(0, d - (n - 1));
        int end = Math.min(m - 1, d);
        if (d % 2 == 0) {
            for (int i = end; i >= start; i--) {
                int j = d - i;
                result[idx++] = mat[i][j];
            }
        } else {
            for (int i = start; i <= end; i++) {
                int j = d - i;
                result[idx++] = mat[i][j];
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;
    // Step 1: find the first index i from right where digits[i] < digits[i+1]
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) { // no higher permutation
        return -1;
    }
    // Step 2: find j, the smallest digit greater than digits[i] to the right
    int j = len - 1;
    while (j > i && digits[j] <= digits[i]) {
        j--;
    }
    // Step 3: swap i and j
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // Step 4: reverse the suffix starting at i+1
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }
    // Convert back to number with overflow check
    long result = 0;
    for (char d : digits) {
        result = result * 10 + (d - '0');
        if (result > Integer.MAX_VALUE) {
            return -1; // overflow, cannot represent in int
        }
    }
    return (int) result;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result; // return empty list for non-positive input
    }
    result.addAll(generateStrobogrammatic(n, n));
    return result;
}

private static List<String> generateStrobogrammatic(int current, int totalLength) {
    List<String> result = new ArrayList<>();
    if (current == 0) {
        result.add("");
        return result;
    }
    if (current == 1) {
        result.add("0");
        result.add("1");
        result.add("8");
        return result;
    }
    List<String> inner = generateStrobogrammatic(current - 2, totalLength);
    for (String s : inner) {
        if (totalLength != current) {
            result.add("0" + s + "0");
        }
        result.add("1" + s + "1");
        result.add("6" + s + "9");
        result.add("8" + s + "8");
        result.add("9" + s + "6");
    }
    return result;
}

public static boolean isBoomerang(int[][] points) {
    // Validate input: must be non-null and contain exactly three 2D points
    if (points == null || points.length != 3) {
        return false;
    }

    // Retrieve each point with bounds checks
    int[] p1 = points[0];
    int[] p2 = points[1];
    int[] p3 = points[2];
    if (p1 == null || p2 == null || p3 == null ||
        p1.length < 2 || p2.length < 2 || p3.length < 2) {
        return false;
    }

    // Use long to avoid int overflow in cross‐product calculation
    long x1 = p1[0], y1 = p1[1];
    long x2 = p2[0], y2 = p2[1];
    long x3 = p3[0], y3 = p3[1];

    long cross = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);

    // Non‑zero cross product indicates the points are not colinear,
    // thus they form a boomerang.
    return cross != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int p2 = 0, p3 = 0, p5 = 0;
    long next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        long next = Math.min(next2, Math.min(next3, next5));
        ugly[i] = (int) next;
        if (next == next2) {
            p2++;
            next2 = (long) ugly[p2] * 2;
        }
        if (next == next3) {
            p3++;
            next3 = (long) ugly[p3] * 3;
        }
        if (next == next5) {
            p5++;
            next5 = (long) ugly[p5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    // Return 0 for null or empty input as there is no non-empty substring
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int maxLen = 1; // longest run seen so far
    int currentLen = 1; // length of the current run

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentLen++; // extend current run
        } else {
            currentLen = 1; // start new run
        }
        if (currentLen > maxLen) {
            maxLen = currentLen;
        }
    }

    return maxLen;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    int current = 1;
    for (int i = 0; i < n; i++) {
        result.add(current);
        if (current <= n / 10) { // can go deeper in prefix
            current *= 10;
        } else {
            // move to next number in lexicographical order
            while (current % 10 == 9 || current + 1 > n) {
                current /= 10;
            }
            current++;
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : nums) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }
    if (n == 0) {
        return 0;
    }

    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            if (dp[i - square] != Integer.MAX_VALUE) {
                dp[i] = Math.min(dp[i], dp[i - square] + 1);
            }
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            result.append(word.reverse());
            word.setLength(0);
            result.append(' ');
        } else {
            word.append(c);
        }
    }
    // Append the last word (if any)
    result.append(word.reverse());

    return result.toString();
}
